text:
{
  "overall": "CV có nền tảng rõ với bán hàng, marketing và hành chính, nhưng phần lớn gạch đầu dòng chỉ mô tả nhiệm vụ. Cần lọc kinh nghiệm, làm nổi bật kết quả và gom kỹ năng theo mục tiêu ứng tuyển.",
  "items": [
    {
      "area": "experience",
      "severity": "high",
      "tip": "Thêm kết quả vào gạch công việc và dự án nếu có: doanh số, số đơn, tương tác fanpage, chi phí quảng cáo, số hồ sơ xử lý."
    },
    {
      "area": "structure",
      "severity": "high",
      "tip": "Rút gọn danh sách kinh nghiệm: giữ các vai trò liên quan nhất, đưa công việc cũ/ít liên quan vào dòng 'Kinh nghiệm khác'."
    },
    {
      "area": "summary",
      "severity": "medium",
      "tip": "Viết lại summary ngắn gọn theo mục tiêu vị trí, nhóm kỹ năng nổi bật và thành tích tiêu biểu nếu có; tránh 'nhiều kinh nghiệm'."
    },
    {
      "area": "skills",
      "severity": "medium",
      "tip": "Gom kỹ năng thành nhóm Bán hàng, Marketing, Hành chính, Tin học, Tiếng Anh; chỉ giữ kỹ năng có bằng chứng trong CV."
    },
    {
      "area": "formatting",
      "severity": "medium",
      "tip": "Với vị trí hiện tại, ghi rõ 'Hiện tại' thay vì ngày kết thúc trống; đồng nhất định dạng tháng-năm và dấu câu."
    },
    {
      "area": "structure",
      "severity": "medium",
      "tip": "Làm rõ các mốc trùng nhau giữa gia sư, tình nguyện, bán online và thu ngân bằng '(kiêm nhiệm)' hoặc '(thời vụ)' nếu đúng."
    },
    {
      "area": "education",
      "severity": "low",
      "tip": "Gộp chứng chỉ tiếng Anh/Tin học vào một mục thống nhất; cân nhắc đưa TOEIC 650 lên gần education nếu vị trí yêu cầu ngoại ngữ."
    },
    {
      "area": "language",
      "severity": "low",
      "tip": "Sửa dòng quá ngắn như 'Phục vụ bàn thời vụ' thành mô tả có phạm vi công việc cụ thể nếu còn giữ lại."
    }
  ]
}
